insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c1c01558-cea6-45c8-9cbc-585e92855f92', 1, 'En el registro 1, 635.222/1.099 = 578 pesos por kWh. En el registro 2, se suman los tres consumos y se multiplican por 578. El total trimestral también permite hallar el promedio, aunque no cada consumo mensual.');

