  'La cantidad total de tapas colocadas debe ser múltiplo de',
  array['3.000.', '4.000.', '7.000.', '11.000.'],
  'Suma las tasas de producción de máquinas que trabajan al mismo tiempo.', 'publicada', 'modelo', '72cb8863e588c1587dbd03688b2c5bf6', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e6cbd003-b35e-4a06-ae34-944282cdfba6', 3, 'Juntas colocan 4.000 + 7.000 = 11.000 tapas por hora. En h horas enteras, el total es 11.000h.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0adfb1d5-cfcf-4ce7-bf56-1baf265c8bac', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '8aa2c370-e568-4b34-9d4a-528d12223fee', 'Proporcionalidad y porcentajes',
  '¿Qué operaciones permiten calcular las ventas de camisas, pantalones y vestidos, respectivamente?',
  array['(1/3)×45.000.000; (1/5)×45.000.000; (1 − 1/3 − 1/5)×45.000.000.', '3 %×45.000.000; 5 %×45.000.000; (100 % − 9 % − 5 %)×45.000.000.', '(1/3) %×45.000; (1/5) %×45.000; (1 − 1/3 − 1/5) %×45.000.', '3×45.000; 5×45.000; (1 − 3 − 5)×45.000.'],
  'El resto se obtiene restando del total las partes ya asignadas.', 'publicada', 'modelo', 'ad46850c74838e1cae58dfc18be8c49b', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0adfb1d5-cfcf-4ce7-bf56-1baf265c8bac', 0, 'Cada fracción multiplica el total de ventas. La parte de vestidos es 1 − 1/3 − 1/5 = 7/15. Las ventas son 15, 9 y 21 millones, cuya suma es 45 millones.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ab2df811-d918-405b-9a9f-89a5c718f299', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'geometria-espacial'),
  (select id from public.lotes where codigo = '2026-B'),
  '5a015c65-e4f9-407c-a080-0cd5ddef0c16', 'Geometría espacial',
  '¿Qué se debe calcular para determinar su volumen usando la altura conocida?',
  array['El área de la base.', 'La suma del radio y el diámetro.', 'El perímetro de la base.', 'La suma de la altura y el área de la base.'],
  'Para un cilindro o prisma, multiplica el área de la base por la altura.', 'publicada', 'modelo', '63059d2ae843337b3acfe5bcd36049b7', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ab2df811-d918-405b-9a9f-89a5c718f299', 0, 'El volumen de un cilindro es área de la base por altura: V = πr²h. El radio es la mitad del diámetro, 0,5 m.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '1cd627b7-6012-4381-8675-e25916c40d7d', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'funciones'),
  (select id from public.lotes where codigo = '2026-B'),
  '8e250472-5c60-431e-8e63-a6fed706828f', 'Funciones y variación',
  '¿Cuáles cantidades permanecen fijas y cuáles varían?',
  array['El costo del domicilio y el número de almuerzos son fijos; el pago total y el precio del almuerzo varían.', 'El pago total y el precio del almuerzo son fijos; el domicilio y el número de almuerzos varían.', 'El costo del domicilio y el precio de cada almuerzo son fijos; el pago total y el número de almuerzos varían.', 'El pago total y el número de almuerzos son fijos; el domicilio y el precio del almuerzo varían.'],
  'Compara el incremento por un almuerzo y la diferencia entre las dos modalidades.', 'publicada', 'modelo', '803fc81c402810b6f2a255b6f6ec623b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1cd627b7-6012-4381-8675-e25916c40d7d', 2, 'Cada almuerzo cuesta $8.000 y el domicilio agrega $2.000 al pedido. Al comprar más almuerzos aumenta el total, pero esas dos tarifas permanecen iguales.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9a45b6fa-9327-4d32-a8d4-a4bd116926ab', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  'f87757db-5d2d-48c1-a398-dd40664cc8e6', 'Estadística descriptiva',
  '¿Cuál es el resultado correcto?',
  array['16, 18, «20», 22, 26, 28, 28.', '16, 18, 22, «23», 26, 28, 28.', '16, 18, 22, «24», 26, 28, 28.', '16, 18, 22, 26, 28, 28, «28».'],
  'Con una cantidad par de datos, promedia los dos valores centrales.', 'publicada', 'modelo', '46f043ae94fe256f4479a205d0bcb176', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9a45b6fa-9327-4d32-a8d4-a4bd116926ab', 2, 'Los datos ordenados son 16, 18, 22, 26, 28, 28. Como hay seis, la mediana es el promedio del tercero y el cuarto: (22 + 26)/2 = 24.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '8534accd-3b9e-4694-8074-6a250860219b', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  '1a1d1d46-9af1-46ca-96f5-80b8be5c45a3', 'Áreas y perímetros',
  '¿Cuál es el área del terreno en pies cuadrados?',
  array['13.500.', '9.000.', '4.500.', '500.'],
  'En una conversión de área, eleva al cuadrado el factor de longitud.', 'publicada', 'modelo', 'ce1a9f53e69cd029d01a7f4acafb4650', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8534accd-3b9e-4694-8074-6a250860219b', 0, 'Una yarda cuadrada contiene 3×3 = 9 pies cuadrados. Por eso 1.500×9 = 13.500 pies cuadrados.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '3f474570-6586-4dc5-8f69-31d37fb74719', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'lectura-de-graficas'),
  (select id from public.lotes where codigo = '2026-B'),
  '5e9ece5f-ce5d-4b55-81cf-61c5b0758a2e', 'Interpretación de datos',
  '¿Qué ocurre al comparar tabla y gráfica?',
  array['Las frecuencias de los hombres están equivocadas.', 'Las frecuencias de las mujeres están equivocadas.', 'Todas las frecuencias están representadas correctamente.', 'El orden de los tipos de medalla justifica las diferencias.'],
  'Verifica cada categoría con su leyenda; no basta con que el total coincida.', 'publicada', 'modelo', 'b13a4b4c0d334a43a09361be2d8c8684', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3f474570-6586-4dc5-8f69-31d37fb74719', 1, 'La gráfica intercambia las cantidades de oro y bronce de las mujeres: deberían ser 20 y 6. Los tres datos de los hombres sí coinciden con la tabla.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '3d029979-ebe1-4836-a687-797856b869be', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'funciones'),
  (select id from public.lotes where codigo = '2026-B'),
  '7db0791f-a369-4b51-b034-5a7220ba925e', 'Funciones y variación',
  '¿Cuál afirmación describe el peso y el estiramiento?',
  array['A mayor peso, mayor estiramiento; el cociente estiramiento/peso es constante.', 'A mayor peso, mayor estiramiento; su producto es constante.', 'A menor peso, mayor estiramiento; su producto es constante.', 'A menor peso, mayor estiramiento; el cociente estiramiento/peso es constante.'],
  'Para comprobar proporcionalidad directa, compara cocientes.', 'publicada', 'modelo', 'd469f98355cbbdf5f5bf99d6c62b29bc', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3d029979-ebe1-4836-a687-797856b869be', 0, 'Los cocientes 6/1, 12/2, 18/3 y 24/4 son todos 6 cm/kg. Es una proporcionalidad directa. Los productos no son constantes.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'dc95523f-8a98-439b-962b-1a60c6ec4ae5', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'funciones'),
  (select id from public.lotes where codigo = '2026-B'),
  '5a59aecc-40df-4c63-9d65-0211bbe8579f', 'Funciones y variación',
  '¿Hay un error en el procedimiento?',
  array['No, porque en el paso 3 se suman correctamente los términos similares.', 'No, porque el signo menos solo afecta al primer término de la segunda expresión.', 'Sí, porque en el paso 2 se distribuye incorrectamente el signo menos.', 'Sí, porque el resultado depende únicamente de la cantidad de artículos.'],
  'Restar un polinomio equivale a sumar el opuesto de cada término.', 'publicada', 'modelo', '08c7d5d73c73f2f55ea94fbb520ab980', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('dc95523f-8a98-439b-962b-1a60c6ec4ae5', 2, 'Al quitar el paréntesis precedido por menos cambian todos sus signos: −x² − x − 3. La diferencia correcta es 2x² − 4x − 6. El error aparece antes de simplificar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '56aad181-9fab-4e51-ba45-c9699f21b702', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'lectura-de-graficas'),
  (select id from public.lotes where codigo = '2026-B'),
  'dd7488a3-6387-4b8c-8818-c2fe7e6238f3', 'Interpretación de datos',
  '¿Cuál afirmación es correcta?',
  array['El sector 1 es el que más familias tiene con 2 o 3 televisores.', 'El sector 3 es el que menos familias tiene con 1 o 2 televisores.', 'Hay más familias con más de 3 televisores que con menos de 1.', 'Hay más familias con 3 o más televisores que con 1 o menos.'],
  'Suma únicamente las filas incluidas en cada condición.', 'publicada', 'modelo', 'e88330a17f6afcc212060ca9fbcf2ee7', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('56aad181-9fab-4e51-ba45-c9699f21b702', 0, 'Las familias con 2 o 3 televisores suman 24, 14 y 19 en los sectores 1, 2 y 3. El mayor total es 24. Las otras comparaciones no se cumplen con los datos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4bfb548a-ce50-4871-acd5-faa00f2c7e91', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  '124adc09-374b-4395-a52e-91643e4d904d', 'Áreas y perímetros',
  'Según la simetría representada en la figura, ¿cuáles afirmaciones son correctas?',
  array['1 y 2.', '1 y 3.', '1 y 4.', '2 y 3.'],
  'Para usar el criterio lado-lado-lado, identifica los tres pares correspondientes.', 'publicada', 'modelo', '77009e1c0dc90881bb073a7c62429114', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4bfb548a-ce50-4871-acd5-faa00f2c7e91', 2, 'En la interpretación simétrica del dibujo, los pares ABD/ACE y BEF/CDF tienen sus tres lados correspondientes iguales. La segunda afirmación iguala segmentos de diferente tamaño y la tercera usa ED = EF en lugar del lado compartido. El original no marca explícitamente las igualdades: requiere revisión docente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '6e3bdeb5-59ae-41a6-bd50-57a6cfa3d151', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  'c1101895-be69-449c-bcd0-26540209eab9', 'Áreas y perímetros',
  '¿Cuál es la suma de los ángulos interiores del orificio?',
  array['360°.', '180°.', '280°.', '140°.'],
  'Cuenta los vértices del orificio, no los del borde exterior de la medalla.', 'publicada', 'modelo', '338273e06f4a98711140a7fb05309506', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6e3bdeb5-59ae-41a6-bd50-57a6cfa3d151', 0, 'El contorno del orificio tiene cuatro vértices, aunque uno apunta hacia adentro. La suma de ángulos interiores de cualquier cuadrilátero simple es (4 − 2)×180° = 360°.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '1cc26b37-c5c2-4f57-ba1b-f281fc3b9282', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  '21496cdd-a34a-4ed7-8e44-3ae247b0ad61', 'Áreas y perímetros',
  '¿Qué cantidad total de cinta necesita?',
  array['42a.', '30a.', '53a.', '40a.'],
  'Cuenta los cuadros de cada cateto y calcula las diagonales con Pitágoras.', 'publicada', 'modelo', 'c23edb697adc0f3221ddd8b44d75eb1d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1cc26b37-c5c2-4f57-ba1b-f281fc3b9282', 0, 'Por Pitágoras, las hipotenusas miden 13a y 5a. Los perímetros son (5 + 12 + 13)a = 30a y (3 + 4 + 5)a = 12a. Al sumar se obtiene 42a.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '252c75e4-963c-4dcb-ad22-7e3f20b70cbe', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'ecuaciones-en-contexto'),
  (select id from public.lotes where codigo = '2026-B'),
  '69b7703d-0376-44d7-bc0e-980a4c2d4e42', 'Ecuaciones en contexto',
  '¿Cuánto le falta ahorrar?',
  array['$19.950.', '$19.580.', '$19.050.', '$25.000.'],
  'Escribe el ahorro de cada día antes de sumar.', 'publicada', 'modelo', '46883255115698e86dbe3b855d02496e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('252c75e4-963c-4dcb-ad22-7e3f20b70cbe', 0, 'Los ahorros son 25.000, 29.050, 50.000 y 51.000. Suman 155.050; faltan 175.000 − 155.050 = 19.950 pesos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9219a7ba-6e67-429e-b97f-517095cd1693', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '8901e616-94b3-4b43-9af6-59ce61afa9ff', 'Proporcionalidad y porcentajes',
  'Si el almacén compra ocho docenas, ¿cuánto paga y cuántas camisetas recibe?',
  array['Paga $150.000 y recibe 96.', 'Paga $240.000 y recibe 192.', 'Paga $240.000 y recibe 112.', 'Paga $150.000 y recibe 112.'],
  'Separa las unidades pagadas de las regaladas.', 'publicada', 'modelo', '7621df17d3d17029eb29b5eb1ed1598e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9219a7ba-6e67-429e-b97f-517095cd1693', 2, 'Ocho docenas son 96 camisetas pagadas: 96×2.500 = 240.000. El regalo es de 8×2 = 16 camisetas; recibe 96 + 16 = 112.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '91d7039f-aa87-4397-80c5-f655ea0689a1', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
  (select id from public.lotes where codigo = '2026-B'),
  'fd5934f2-082f-47fb-af8a-b4f860af8c49', 'Proporcionalidad y porcentajes',
  '¿Qué porcentaje hace ejercicio al menos una vez cada 20 días?',
  array['55 %.', '27 %.', '16 %.', '45 %.'],
  'Incluye las frecuencias cuyo intervalo no supera los 20 días.', 'publicada', 'modelo', '78bab0e2945eba4af8819e7ce06f7dff', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('91d7039f-aa87-4397-80c5-f655ea0689a1', 3, 'Cumplen la condición quienes hacen ejercicio a diario, semanalmente o cada 15 días: 180 + 360 + 360 = 900. El porcentaje es 900/2.000×100 = 45 %.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a6d12af6-5961-444e-9d0b-78b43ecb776d', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'funciones'),
  (select id from public.lotes where codigo = '2026-B'),
  'dfe8f9a6-9700-4fa4-b5e1-11a27a7abff2', 'Funciones y variación',
  '¿Cuáles afirmaciones son correctas?',
  array['1 y 2.', '2 solamente.', '1 solamente.', '2 y 3.'],
  'Lee las unidades del eje: la altura representa velocidad y la pendiente representa aceleración.', 'publicada', 'modelo', 'dcef389739f1e37c24471844dfbfb555', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a6d12af6-5961-444e-9d0b-78b43ecb776d', 2, 'La aceleración es la pendiente de velocidad frente a tiempo. Para Camila vale 6/3 = 2 km/h². El 9 del último punto de Martha es una velocidad en km/h, no una aceleración: en el último tramo la pendiente es (9 − 6)/(3 − 2,5) = 6 km/h². La afirmación 2 confunde las unidades del eje. Esta diferencia con la redacción original requiere revisión docente.');

